use App\Support\Database;
return static function(Database $db):void{
 $db->execute("CREATE TABLE IF NOT EXISTS investment_positions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,wallet_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,investment_offering_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,currency_code CHAR(3) NOT NULL,company_name_snapshot VARCHAR(255) NOT NULL,quantity DECIMAL(20,8) NOT NULL,share_price_minor_snapshot BIGINT UNSIGNED NOT NULL,principal_amount_minor BIGINT UNSIGNED NOT NULL,profit_type_snapshot ENUM('FIXED','PERCENTAGE') NOT NULL,projected_profit_value_snapshot DECIMAL(20,8) NOT NULL,fixed_profit_basis_snapshot ENUM('PER_SHARE','PER_INVESTMENT') NULL,projected_profit_amount_minor BIGINT UNSIGNED NOT NULL,duration_value_snapshot SMALLINT UNSIGNED NOT NULL,duration_unit_snapshot ENUM('DAYS','WEEKS','MONTHS','YEARS') NOT NULL,purchased_at DATETIME NOT NULL,maturity_date DATETIME NOT NULL,matured_at DATETIME NULL,sold_at DATETIME NULL,status ENUM('ACTIVE','SALE_REQUESTED','SALE_APPROVED','SOLD','MATURED','CANCELLED','SUSPENDED') NOT NULL DEFAULT 'ACTIVE',purchase_ledger_transaction_id BIGINT UNSIGNED NOT NULL,maturity_principal_ledger_transaction_id BIGINT UNSIGNED NULL,maturity_profit_ledger_transaction_id BIGINT UNSIGNED NULL,metadata JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY investment_public(public_id),UNIQUE KEY investment_purchase_ledger(purchase_ledger_transaction_id),INDEX investments_user_status(user_id,status,purchased_at),INDEX investments_maturity(status,maturity_date),INDEX investments_offering_status(investment_offering_id,status),CONSTRAINT fk_investment_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_investment_wallet FOREIGN KEY(wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,CONSTRAINT fk_investment_company FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT,CONSTRAINT fk_investment_offering FOREIGN KEY(investment_offering_id) REFERENCES investment_offerings(id) ON DELETE RESTRICT,CONSTRAINT fk_investment_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,CONSTRAINT fk_investment_purchase_ledger FOREIGN KEY(purchase_ledger_transaction_id) REFERENCES ledger_transactions(id) ON DELETE RESTRICT,CONSTRAINT fk_investment_principal_ledger FOREIGN KEY(maturity_principal_ledger_transaction_id) REFERENCES ledger_transactions(id) ON DELETE RESTRICT,CONSTRAINT fk_investment_profit_ledger FOREIGN KEY(maturity_profit_ledger_transaction_id) REFERENCES ledger_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->execute("CREATE TABLE IF NOT EXISTS sale_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,public_id CHAR(36) NOT NULL,reference VARCHAR(80) NOT NULL,investment_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,country_id BIGINT UNSIGNED NOT NULL,requested_quantity DECIMAL(20,8) NOT NULL,requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,status ENUM('PENDING','UNDER_REVIEW','APPROVED','REJECTED','CANCELLED') NOT NULL DEFAULT 'PENDING',sale_pricing_mode ENUM('CURRENT_PLATFORM_PRICE','ORIGINAL_PURCHASE_PRICE','ADMIN_APPROVED_PRICE') NOT NULL DEFAULT 'CURRENT_PLATFORM_PRICE',sale_price_minor_snapshot BIGINT UNSIGNED NULL,sale_value_minor BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,reviewed_by_user_id BIGINT UNSIGNED NULL,rejection_reason TEXT NULL,admin_notes TEXT NULL,sale_ledger_transaction_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,UNIQUE KEY sale_public(public_id),UNIQUE KEY sale_reference(reference),UNIQUE KEY sale_ledger(sale_ledger_transaction_id),INDEX sale_investment_status(investment_id,status),CONSTRAINT fk_sale_investment FOREIGN KEY(investment_id) REFERENCES investment_positions(id) ON DELETE RESTRICT,CONSTRAINT fk_sale_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_sale_country FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT,CONSTRAINT fk_sale_reviewer FOREIGN KEY(reviewed_by_user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_sale_ledger FOREIGN KEY(sale_ledger_transaction_id) REFERENCES ledger_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
